import {elements,colors,classes,pets,skills,zones,chapters,fresh,validate,elapsed,stats,attack,upgrade,learn,rate,synergy} from './engine.js';
import {drawWorld} from './world.js';
import {assetUrl,iconUrl,companions,installArtUI,loadAllArt} from './art.js';
loadAllArt().then(r=>{const failed=r.filter(a=>!a.ok);document.querySelector('#art-status').textContent=failed.length?'Một số hình chưa tải được · Hãy tải lại trang':'';});
const $=s=>document.querySelector(s),key='linhkhi-v1';let s=fresh(),tab='skills',fight=null,logs=[],effect=null,saveError=false;
function log(t){logs.unshift(t);logs=logs.slice(0,15);$('#log').replaceChildren(...logs.map(t=>{const p=document.createElement('p');p.textContent=t;return p;}));}
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.opacity=0,3200);}
function save(){try{const old=localStorage.getItem(key);if(old){try{validate(JSON.parse(old));localStorage.setItem(key+'-backup',old);}catch{}}localStorage.setItem(key,JSON.stringify(s));$('#save-state').textContent='Đã lưu trên máy';saveError=false;}catch{if(!saveError)toast('Không lưu được. Hãy xuất bản lưu để giữ tiến độ.');saveError=true;$('#save-state').textContent='Lưu thất bại';}}
let recovered=false;for(const k of [key,key+'-backup']){try{const raw=localStorage.getItem(k);if(raw){s=validate(JSON.parse(raw));recovered=k!==key;break;}}catch{recovered=true;}}
const away=elapsed(s);if(away.sec>60)log(`Trở về sau ${Math.floor(away.sec/60)} phút: +${Math.floor(away.qi)} tu vi, +${away.stones} linh thạch.`);if(recovered)log('Bản lưu chính có vấn đề. Đã thử khôi phục bản dự phòng.');
function modal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
$('#close-modal').onclick=()=>$('#modal').close();
function stage(){if(s.choices.every(Boolean))return 6;let z=s.choices.findIndex(x=>!x);return z*2+(s.wins[z]>=3?1:0);}
function render(){installArtUI(s);const p=stats(s),cost=[100,450,0][s.realm];$('#qi').textContent=Math.floor(s.qi).toLocaleString('vi');$('#stones').textContent=Math.floor(s.stones).toLocaleString('vi');$('#realm').textContent=['Cảm Linh · Sơ nhập','Luyện Khí · Tụ linh','Trúc Cơ · Vững đạo'][s.realm];$('#progress').style.width=(cost?Math.min(100,s.qi/cost*100):100)+'%';$('#progress-text').textContent=cost?`${Math.floor(s.qi)} / ${cost} tu vi · +${rate(s).toFixed(1)}/giây`:'Đã đạt cảnh giới cao nhất bản demo';$('#breakthrough').disabled=!!fight||s.realm===2||s.qi<cost||(s.realm===1&&!s.cleared[0]);$('#breakthrough').title=s.realm===1&&!s.cleared[0]?'Cần vượt Thạch Vệ trước khi Trúc Cơ':'';$('#stats').innerHTML=`<div><b>${p.atk}</b><small>Công kích</small></div><div><b>${p.hp}</b><small>Sinh lực</small></div><div><b>${p.armor}</b><small>Hộ thể</small></div><div><b>${s.body}</b><small>Luyện thể</small></div>`;$('#class').value=s.cls;$('#class').disabled=!!fight;$('#class-desc').textContent=['Thuật pháp bộc phát mỗi 3 lượt. Mạnh về sát thương.','Sinh lực cao, giảm sát thương và phản kích mỗi 3 lượt.','Linh thú hợp kích mỗi lượt, hồi phục mạnh hơn.'][s.cls];$('#elements').innerHTML=elements.map((e,i)=>`<button data-element="${i}" ${fight?'disabled':''} class="${s.element===i?'selected':''}" title="Linh căn ${e}">${e}</button>`).join('');$('#zone-title').textContent=zones[s.zone].name;$('#zone-sub').textContent=zones[s.zone].sub;$('#element-tag').textContent=elements[zones[s.zone].element].toUpperCase()+' · KHU VỰC '+(s.zone+1);$('#locations').innerHTML=zones.map((z,i)=>`<button data-zone="${i}" class="${s.zone===i?'selected':''}" ${fight||(i>0&&!s.choices[i-1])?'disabled':''}>${i>0&&!s.choices[i-1]?'⌑':'◇'} ${z.name}<small>${s.choices[i]?'Đã giải phóng':i>s.zone&&!s.choices[i-1]?'Chưa mở':`${Math.min(s.wins[i],3)}/3 đợt tuần tra`}</small></button>`).join('');$('#patrol').textContent=fight?'Rút lui':s.mode==='patrol'?'Dừng tuần tra':'Tuần tra';$('#patrol').disabled=false;$('#boss').disabled=!!fight||s.wins[s.zone]<3||s.cleared[s.zone];$('#boss').textContent=s.cleared[s.zone]?'Đã vượt thủ lĩnh ✓':'Thử thách thủ lĩnh ⚔';$('#encounter-title').textContent=fight?fight.name:s.cleared[s.zone]?'Khu vực an toàn · Có thể tự động tuần tra':'Giải quyết nhiễu linh';$('#encounter-desc').textContent=fight?'Tự động ra đòn mỗi giây · Có thể đổi chiến thuật sau trận':`${Math.min(s.wins[s.zone],3)}/3 đợt trước thủ lĩnh · Khắc hệ +15% sát thương`;$('#activity').textContent=fight?'⚔ Đang giao chiến':s.mode==='patrol'?'◇ Tuần tra tự động':'✧ Đang hấp thu linh khí';const st=stage(),ch=chapters[Math.min(st,5)];$('#chapter-title').textContent=st===6?'An Hòa đón bình minh':ch.title;$('#chapter-text').textContent=st===6?ending():ch.text;$('#quest-text').textContent=st===6?'Chương I hoàn tất. Tiếp tục thử các đạo lộ và tổ hợp ngũ hành.':ch.goal;$('#quest-progress').textContent=st===6?'6 / 6 nhiệm vụ hoàn thành':`${Math.min(s.wins[Math.floor(st/2)],3)} / 3 đợt · ${['Cảm Linh','Luyện Khí','Trúc Cơ'][s.realm]}`;$('#combat-hud').hidden=!fight;if(fight){$('#hero-label').textContent=`Lữ khách · ${Math.ceil(fight.hp)}/${fight.maxHp}`;$('#enemy-label').textContent=`${fight.name} · ${Math.max(0,Math.ceil(fight.enemy))}/${fight.maxEnemy}`;$('#hero-hp').style.width=fight.hp/fight.maxHp*100+'%';$('#enemy-hp').style.width=Math.max(0,fight.enemy/fight.maxEnemy*100)+'%';}renderTab();}
function ending(){const h=s.choices.filter(x=>x==='heal').length;return h>=2?'Bạn đưa linh khí trở về khu phố. Thạch linh sửa lại con hẻm, cây cối che bóng cho quán nước, và giọng nói ở ga cuối cùng được nghỉ ngơi. An Hòa lập khế ước chung sống. Trong chiếc radio cũ, một tín hiệu từ khu Đông vang lên…':'Thiết bị Bình Minh đã ngừng hoạt động. Bạn niêm phong các linh thể nguy hiểm và dựng kết giới cho An Hòa. Thành phố được an toàn, nhưng ga metro trở nên im lặng. Trong chiếc radio cũ, một tín hiệu từ khu Đông vang lên…';}
let tabRenderKey="";function renderTab(){const next=JSON.stringify([tab,s.cls,s.pet,s.relic,s.stones,s.body,s.gear,s.learned,!!fight,stage()]);if(next===tabRenderKey)return;tabRenderKey=next;const el=$('#tab-content');if(tab==='skills'){el.innerHTML=`<div class="help">${classes[s.cls]} · Hai hướng: các nút lẻ tăng hộ thể, các nút chẵn tăng công kích.<br>Mỗi hướng học lần lượt từ trên xuống. Đổi đạo lộ miễn phí ngoài trận.</div><div class="cards" style="margin-top:14px">${skills[s.cls].map((n,i)=>`<div class="card ${s.learned[s.cls].includes(i)?'chosen':''}"><img class="skill-icon" src="${iconUrl(s.cls,i)}" alt="" width="62" height="62"><h3>${n}</h3><p>${i%2?'+5 công kích':'+12 sinh lực'}${i>1?' · Cần '+skills[s.cls][i-2]:''}</p><button data-learn="${i}" ${fight||s.learned[s.cls].includes(i)||s.stones<25+i*20||(i>1&&!s.learned[s.cls].includes(i-2))?'disabled':''}>${s.learned[s.cls].includes(i)?'Đã lĩnh ngộ ✓':`Học · ${25+i*20} ◇`}</button></div>`).join('')}</div>`;}else if(tab==='gear'){el.innerHTML=`<div class="cards"><div class="card"><h3>Luyện thể ${s.body}</h3><p>+25 sinh lực, +2 hộ thể mỗi cấp.</p><button data-up="body" ${fight||s.stones<30+s.body*20?'disabled':''}>Rèn luyện · ${30+s.body*20} ◇</button></div><div class="card"><h3>Linh trang +${s.gear}</h3><p>Vũ khí hợp nhất · +4 công kích mỗi cấp.</p><button data-up="gear" ${fight||s.stones<35+s.gear*25?'disabled':''}>Cường hóa · ${35+s.gear*25} ◇</button></div></div><p class="help">Trang bị một pháp bảo. Có thể đổi miễn phí ngoài trận.</p><div class="cards">${['Vòng Đồng|+12% sát thương kỹ năng','Ngọc Bình An|Giảm 15% sát thương nhận','Ấn Phá Vọng|+8% mọi sát thương'].map((v,i)=>`<div class="card ${s.relic===i?'chosen':''}"><h3>${v.split('|')[0]}</h3><p>${v.split('|')[1]}</p><button data-relic="${i}" ${fight?'disabled':''}>${s.relic===i?'Đang trang bị ✓':'Trang bị'}</button></div>`).join('')}</div>`;}else if(tab==='pets'){el.innerHTML=`<p class="help">Tương sinh: Mộc → Hỏa → Thổ → Kim → Thủy → Mộc. Linh thú sinh linh căn của bạn: +12% sát thương. ${synergy(s.pet,s.element)?'✧ Đang cộng hưởng!':''}</p><div class="cards">${pets.map((n,i)=>`<div class="card ${s.pet===i?'chosen':''}"><img class="pet-art" src="${assetUrl(companions[i])}" alt="${n}"><h3>${n}</h3><p>${elements[i]} · ${['Xuyên giáp +3','Hồi 3 sinh lực/lượt','Giảm 10% sát thương nhận','Sát thương +4','Hồi 2 sinh lực/lượt'][i]}</p><button data-pet="${i}" ${fight?'disabled':''}>${s.pet===i?'Đồng hành ✓':'Kết giao'}</button></div>`).join('')}</div>`;}else{el.innerHTML=chapters.map((c,i)=>`<div class="journal-entry"><b>${i<=stage()?c.title:'⌑ Chưa khám phá'}</b>${i<=stage()?`<p>${c.text}</p>`:''}</div>`).join('');}}
$('#class').innerHTML=classes.map((v,i)=>`<option value="${i}">${v}</option>`).join('');$('#class').onchange=e=>{if(fight)return;s.cls=Number(e.target.value);save();render();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.tab){tab=d.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderTab();return;}if(fight)return;for(const k of ['element','pet','relic'])if(d[k]!==undefined){s[k]=Number(d[k]);save();render();return;}if(d.zone!==undefined){const z=Number(d.zone);if(z>0&&!s.choices[z-1])return;s.zone=z;s.mode='rest';save();render();}if(d.learn!==undefined&&learn(s,Number(d.learn))){toast('Đã lĩnh ngộ '+skills[s.cls][Number(d.learn)]);save();render();}if(d.up&&upgrade(s,d.up)){toast('Tu luyện thành công');save();render();}});
$('#breakthrough').onclick=()=>{if(upgrade(s,'realm')){toast('Đột phá thành công!');log('Cảnh giới mới: '+['Cảm Linh','Luyện Khí','Trúc Cơ'][s.realm]);save();render();}};
function start(boss=false){if(fight)return;const z=zones[s.zone];if(boss&&(s.wins[s.zone]<3||s.cleared[s.zone]))return;const hp=z.hp*(boss?2.4:1),p=stats(s);fight={name:boss?z.boss:z.enemies[s.wins[s.zone]%3],boss,hp:p.hp,maxHp:p.hp,enemy:hp,maxEnemy:hp,atk:z.atk*(boss?1.6:1),tick:0};render();}
$('#patrol').onclick=()=>{if(fight){fight=null;s.mode='rest';save();render();return;}if(s.mode==='patrol'){s.mode='rest';save();render();return;}s.mode='patrol';start();save();};$('#boss').onclick=()=>{s.mode='rest';start(true);};
function choose(z){modal(`<div class="eyebrow">LA BÀN ĐẠO TÂM</div><h2>${zones[z].boss} đã bình tĩnh lại</h2><p>${['Dưới lớp đá, số nhà 17 vẫn còn nguyên. Người gác hẻm đang đợi quyết định của bạn.','Mộc Miên đặt một chiếc lá lên bàn tay bạn. Khu vườn có thể hồi sinh.','Dòng nước phản chiếu hàng trăm gương mặt. Giữ ký ức ấy, hay đóng lại ga mãi mãi?'][z]}</p><button id="heal" class="primary">Thanh tẩy · +0,2 tu vi/giây vĩnh viễn</button><button id="seal">Trấn áp · Nhận ngay 100 linh thạch</button><p class="help">Lựa chọn được lưu và ảnh hưởng kết thúc chương.</p>`);for(const choice of ['heal','seal'])$('#'+choice).onclick=()=>{if(s.choices[z])return;s.choices[z]=choice;if(choice==='seal')s.stones+=100;log(choice==='heal'?'Một sinh linh mới trở thành hàng xóm của An Hòa.':'Đã niêm phong linh thể, khu vực được bảo vệ.');if(z<2)s.zone=z+1;save();$('#modal').close();render();if(z===2)modal(`<div class="eyebrow">HOÀN THÀNH CHƯƠNG I</div><h2>An Hòa đón bình minh</h2><p>${ending()}</p><p class="help">Bạn có thể tiếp tục tu luyện, thử đạo lộ khác và xuất bản lưu.</p>`);};}
function combat(){if(!fight)return;const f=fight;f.tick++;const hit=attack(s,f.tick);let damage=hit.damage+(s.pet===0?3:s.pet===3?4:0);f.enemy-=damage;effect={time:performance.now(),damage,skill:hit.skill};if(f.enemy<=0){const boss=f.boss;fight=null;s.stones+=boss?75+s.zone*40:14+s.zone*8;s.qi+=boss?50:12;if(boss){s.cleared[s.zone]=true;s.mode='rest';log('Đã vượt '+f.name+' · nhận tu vi và linh thạch.');save();choose(s.zone);}else{s.wins[s.zone]++;log('Vượt '+f.name+` · +${14+s.zone*8} linh thạch`);if(!s.cleared[s.zone]&&s.wins[s.zone]>=3){s.mode='rest';toast('Thủ lĩnh đã xuất hiện. Chuẩn bị và chọn thử thách!');}save();}render();return;}const p=stats(s),incoming=Math.max(1,f.atk-p.armor)*(s.relic===1?.85:1)*(s.pet===2?.9:1)*(s.element===4?.9:1);f.hp-=incoming;f.hp=Math.min(f.maxHp,f.hp+p.heal+(s.pet===4?2:0)+(s.cls===2?3:0)+(s.element===1?2:0));if(s.cls===1&&f.tick%3===0)f.enemy-=5+s.body*2;if(f.hp<=0){fight=null;s.mode='rest';log('Tạm lui về. Hãy tăng luyện thể, đổi pháp bảo hoặc chọn linh căn khắc hệ.');toast('Chưa vượt được · Không mất tài nguyên');save();}render();}
let last=Date.now(),saveClock=0;setInterval(()=>{const now=Date.now(),gap=now-last;last=now;if(gap>10000){fight=null;const r=elapsed(s,now);log(`Nghỉ ngơi: +${Math.floor(r.qi)} tu vi, +${r.stones} linh thạch.`);}else{s.qi+=Math.max(0,gap/1000)*rate(s);s.at=now;combat();if(!fight&&s.mode==='patrol')start();}if(++saveClock%5===0)save();render();},1000);
document.addEventListener('visibilitychange',()=>{if(document.hidden){s.at=Date.now();save();}else{const r=elapsed(s);last=Date.now();fight=null;if(r.sec>5)log(`Trở lại: +${Math.floor(r.qi)} tu vi, +${r.stones} linh thạch.`);render();}});window.addEventListener('pagehide',()=>{s.at=Date.now();save();});
$('#read-story').onclick=()=>modal(`<div class="eyebrow">CHƯƠNG I · AN HÒA</div><h2>${stage()===6?'Bình minh trở lại':chapters[stage()].title}</h2><p>${stage()===6?ending():chapters[stage()].text}</p>${s.cleared[s.zone]&&!s.choices[s.zone]?'<button id="resolve" class="primary">Quyết định số phận linh thể</button>':''}`);$('#modal-body').addEventListener('click',e=>{if(e.target.id==='resolve')choose(s.zone);});
$('#settings').onclick=()=>{modal('<h2>Bản lưu của bạn</h2><p>Tiến độ lưu riêng trên trình duyệt này. Xuất tệp để chuyển máy hoặc dự phòng.</p><button id="export" class="primary">Xuất bản lưu JSON</button><p><label for="import">Khôi phục từ tệp JSON (thay thế tiến độ hiện tại)</label><input id="import" type="file" accept="application/json,.json"></p><p class="help">Ngoại tuyến tối đa 12 giờ. Tu vi luôn tích lũy; linh thạch ngoại tuyến chỉ có khi tuần tra khu vực đã vượt thủ lĩnh. Bản thử nghiệm một người chơi, không đồng bộ đám mây.</p>');$('#export').onclick=()=>{save();const u=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='linh-khi-an-hoa.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('Tệp quá lớn.');const data=validate(JSON.parse(await f.text()));if(!confirm('Thay thế tiến độ hiện tại bằng bản lưu đã chọn?'))return;s=data;elapsed(s);fight=null;last=Date.now();save();render();$('#modal').close();toast('Đã khôi phục tiến độ');}catch(err){toast('Không thể nhập: '+err.message);}};};
let lastFrame=0;function frame(t){if(!document.hidden&&t-lastFrame>32){drawWorld($('#world'),s,fight,effect,t);lastFrame=t;}requestAnimationFrame(frame);}requestAnimationFrame(frame);render();
if(!s.started){modal('<div class="eyebrow">CHÀO MỪNG ĐẾN AN HÒA</div><h2>Khi thành phố ngủ,<br>linh khí thức giấc.</h2><p>02:17 sáng. Một con mèo vừa gọi tên bạn. Trên sân thượng, cả bầu trời đang chảy thành những dải sáng.</p><p>Chọn đạo lộ và linh căn ở bảng nhân vật. Tuần tra 3 đợt để tìm thủ lĩnh. Dùng linh thạch học công pháp, luyện thể và cường hóa. Tu vi tự tích lũy để đột phá.</p><button id="begin" class="primary">Bước vào An Hòa →</button><p class="help">Demo tăng tốc để thử cơ chế · Đổi nhánh miễn phí · Tự lưu</p>');$('#begin').onclick=()=>{s.started=true;save();$('#modal').close();log('Bà Tư: “Giữ con hẻm trước đã, chuyện thành tiên tính sau.”');};}else{const unresolved=s.cleared.findIndex((v,i)=>v&&!s.choices[i]);if(unresolved>=0)choose(unresolved);}

